 /**

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug arises from the failure to reset the receive buffer size after consecutive commands that fetch descriptors. When the response size from the firmware exceeds the previously set size, the system may incorrectly interpret the response, leading to potential data corruption or miscommunication. This occurs because the receive buffer retains the size from the last command, which may not be appropriate for the current command's response.

        Commit message:
        firmware: arm_scmi: Add missing Rx size re-initialisation

Few commands provide the list of description partially and require
to be called consecutively until all the descriptors are fetched
completely. In such cases, we don't release the buffers and reuse
them for consecutive transmits.

However, currently we don't reset the Rx size which will be set as
per the response for the last transmit. This may result in incorrect
response size being interpretted as the firmware may repond with size
greater than the one set but we read only upto the size set by previous
response.

Let us reset the receive buffer size to max possible in such cases as
we don't know the exact size of the response.

Link:  https://lore.kernel.org/r/20201012141746.32575-1-sudeep.holla@arm.com
Fixes: b6f20ff8bd94 ("firmware: arm_scmi: add common infrastructure and support for base protocol")
Reported-by: Etienne Carriere <etienne.carriere@linaro.org>
Signed-off-by: Sudeep Holla <sudeep.holla@arm.com>  

        Patch:

 static int
 scmi_perf_describe_levels_get(const struct scmi_handle *handle, u32 domain,
 			      struct perf_dom_info *perf_dom)
 {
 	int ret, cnt;
 	u32 tot_opp_cnt = 0;
 	u16 num_returned, num_remaining;
 	struct scmi_xfer *t;
 	struct scmi_opp *opp;
 	struct scmi_msg_perf_describe_levels *dom_info;
 	struct scmi_msg_resp_perf_describe_levels *level_info;

 	ret = scmi_xfer_get_init(handle, PERF_DESCRIBE_LEVELS,
 				 SCMI_PROTOCOL_PERF, sizeof(*dom_info), 0, &t);
 	if (ret)
 		return ret;

 	dom_info = t->tx.buf;
 	level_info = t->rx.buf;

 	do {
 		dom_info->domain = cpu_to_le32(domain);
 		/* Set the number of OPPs to be skipped/already read */
 		dom_info->level_index = cpu_to_le32(tot_opp_cnt);

 		ret = scmi_do_xfer(handle, t);
 		if (ret)
 			break;

 		num_returned = le16_to_cpu(level_info->num_returned);
 		num_remaining = le16_to_cpu(level_info->num_remaining);
 		if (tot_opp_cnt + num_returned > MAX_OPPS) {
 			dev_err(handle->dev, "No. of OPPs exceeded MAX_OPPS");
 			break;
 		}

 		opp = &perf_dom->opp[tot_opp_cnt];
 		for (cnt = 0; cnt < num_returned; cnt++, opp++) {
 			opp->perf = le32_to_cpu(level_info->opp[cnt].perf_val);
 			opp->power = le32_to_cpu(level_info->opp[cnt].power);
 			opp->trans_latency_us = le16_to_cpu
 				(level_info->opp[cnt].transition_latency_us);

 			dev_dbg(handle->dev, "Level %d Power %d Latency %dus\n",
 				opp->perf, opp->power, opp->trans_latency_us);
 		}

 		tot_opp_cnt += num_returned;
+
+		scmi_reset_rx_to_maxsz(handle, t);
 		/*
 		 * check for both returned and remaining to avoid infinite
 		 * loop due to buggy firmware
 		 */
 	} while (num_returned && num_remaining);

 	perf_dom->opp_count = tot_opp_cnt;
 	scmi_xfer_put(handle, t);

 	sort(perf_dom->opp, tot_opp_cnt, sizeof(*opp), opp_cmp_func, NULL);
 	return ret;
 }



